function model = bouncing()
%BOUNCING Build and save the Simulink model of the assembly 'bouncing.fmu'.
%   Generated by the FMU Manipulation Toolbox. Run it in MATLAB R2024a or newer: it builds the model with
%   FMU blocks and saves it as bouncing_model.slx next to this script. The FMUs stay in their folders,
%   relative to this script.

here = fileparts(mfilename('fullpath'));
addpath(here);
load_system('simulink_extras');
model = 'bouncing_model';
if bdIsLoaded(model)
    close_system(model, 0);
end
new_system(model);
set_param(model, 'SolverType', 'Fixed-step', 'FixedStep', '0.001', 'EnableMultiTasking', 'off', 'BlockReduction', 'off');
set_param(model, 'PreLoadFcn', 'here = fileparts(get_param(bdroot, ''FileName'')); addpath(here);');  % UNVERIFIED

% System 'bouncing'
add_block('simulink_extras/FMU Import/FMU', [model '/bb_position'], 'Position', [380 40 500 100]);
set_param([model '/bb_position'], 'FMUName', 'bb_position.fmu', 'FMUInputMapping', 'Flat', 'FMUOutputMapping', 'Flat', 'FMUSampleTime', '0.001');
ports = get_param([model '/bb_position'], 'PortHandles');
for k = 1:numel(ports.Inport)
    set_param(ports.Inport(k), 'CoSimSignalCompensationMode', 'Auto_Off');
end
add_block('simulink_extras/FMU Import/FMU', [model '/bb_velocity'], 'Position', [380 140 500 180]);
set_param([model '/bb_velocity'], 'FMUName', 'bb_velocity.fmu', 'FMUInputMapping', 'Flat', 'FMUOutputMapping', 'Flat', 'FMUSampleTime', '0.001');
ports = get_param([model '/bb_velocity'], 'PortHandles');
for k = 1:numel(ports.Inport)
    set_param(ports.Inport(k), 'CoSimSignalCompensationMode', 'Auto_Off');
end
add_block('built-in/Outport', [model '/position'], 'Position', [720 40 750 54]);
set_param([model '/position'], 'Port', '1');
add_block('built-in/Outport', [model '/velocity'], 'Position', [720 94 750 108]);
set_param([model '/velocity'], 'Port', '2');
add_block('built-in/UnitDelay', [model '/bb_velocity.1 delay'], 'Position', [1060 40 1095 74]);
set_param([model '/bb_velocity.1 delay'], 'InitialCondition', '0.0', 'SampleTime', '0.001');

% Lines of 'bouncing'
add_line(model, 'bb_position/1', 'bb_velocity/1', 'autorouting', 'on');
add_line(model, 'bb_velocity/1', 'bb_velocity.1 delay/1', 'autorouting', 'on');
add_line(model, 'bb_velocity.1 delay/1', 'bb_position/1', 'autorouting', 'on');
add_line(model, 'bb_position/2', 'position/1', 'autorouting', 'on');
add_line(model, 'bb_velocity/1', 'velocity/1', 'autorouting', 'on');
Simulink.BlockDiagram.arrangeSystem(model);
restore_default_sizes(model);
save_system(model, fullfile(here, [model '.slx']));
end

function restore_default_sizes(system)
%RESTORE_DEFAULT_SIZES Default size of the small blocks of a system, around their center (arrangeSystem
%   resizes them).
sizes = {'Inport', [30 14]; 'Outport', [30 14]; 'Constant', [30 30]; 'Terminator', [20 20]; 'UnitDelay', [35 34]};
for i = 1:size(sizes, 1)
    blocks = find_system(system, 'SearchDepth', 1, 'BlockType', sizes{i, 1});
    for j = 1:numel(blocks)
        position = get_param(blocks{j}, 'Position');
        center = [(position(1) + position(3)) / 2, (position(2) + position(4)) / 2];
        half = round(sizes{i, 2} / 2);
        set_param(blocks{j}, 'Position', [center - half, center + half]);
    end
end
end
